package com.abhishek.hotelbooking.repository; import com.abhishek.hotelbooking.entity.Room; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface RoomRepository extends JpaRepository<Room,Long>{ List<Room> findByHotelIdAndActiveTrue(Long hotelId); @Query("select r from Room r where r.hotel.id=:hotelId and r.active=true and not exists (select b.id from Booking b where b.room=r and b.status='CONFIRMED' and b.checkIn < :checkOut and b.checkOut > :checkIn)") List<Room> findAvailable(@Param("hotelId") Long hotelId,@Param("checkIn") LocalDate checkIn,@Param("checkOut") LocalDate checkOut); }